script:
(function () {
  'use strict';
  // Mortgage APR with each closing cost sorted into finance charge or not, per Regulation Z
  // (12 CFR 1026.4, read on eCFR this session). Finance charges: points, loan and origination fees
  // and service charges (4(b)(2)-(3)), mortgage broker fees (4(a)(3)), mortgage insurance (4(b)(5)) and
  // interest, including per diem interest collected at closing (4(b)(1)). Not finance charges:
  // application fees charged to all applicants (4(c)(1)) and bona fide, reasonable real-estate fees
  // for title, document preparation, notary, credit report and appraisal (4(c)(7)).
  //   Amount financed A = loan - prepaid finance charges (points, origination, lender and broker fees,
  //   upfront mortgage insurance, prepaid interest = loan x rate / 365 x days).
  //   Payments = P&I (rounded to the cent) + monthly mortgage insurance (annual % x loan / 12) for each
  //   payment until the scheduled balance first reaches 78% of the original value (the Homeowners
  //   Protection Act termination date, 12 U.S.C. 4901-4902).
  //   APR = 12 x j where sum P_k / (1 + j)^k = A (bisection). Tolerance: 1/8 point for regular
  //   payments, 1/4 point for irregular ones (1026.22(a)(2)-(3)).
  // Verified in Node (scratchpad mtg6/tests/aprm.test.js): no charges -> APR = note rate (6.500%);
  //   $280,000 at 6.2% for 30 years with $3,500 fees and 0.5 points -> P&I $1,714.91, APR 6.367%
  //   (same as the live apr-calculator's verified case); $320,000 at 6.5% on a $350,000 home ->
  //   mortgage insurance in 117 payments, matching a direct count of the closed-form balance
  //   against 78% of value; 0% rate, blank, negative and fees >=
  //   loan never reach the page as NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- pure ---
  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  function pvStream(pays, j) {
    var v = 0, d = 1;
    for (var k = 0; k < pays.length; k++) { d /= (1 + j); v += pays[k] * d; }
    return v;
  }

  function solveApr(net, pays) {
    var sum = pays.reduce(function (a, b) { return a + b; }, 0);
    if (net <= 0 || sum <= 0) return NaN;
    if (net >= sum - 1e-9) return 0;
    var lo = 0, hi = 0.05;
    while (pvStream(pays, hi) > net && hi < 100) hi *= 2;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (pvStream(pays, mid) > net) lo = mid; else hi = mid;
    }
    return 12 * (lo + hi) / 2;
  }

  // Payment stream: P&I plus monthly mortgage insurance until the balance is scheduled to reach 78% of value.
  function stream(loan, rate, months, value, miPct) {
    var pi = Math.round(payment(loan, rate, months) * 100) / 100, bal = loan, pays = [], miMonths = 0;
    var mi = loan * miPct / 1200, stop = 0.78 * value;
    for (var m = 0; m < months; m++) {
      var withMi = mi > 0 && bal > stop + 1e-9;
      var interest = bal * rate / 1200;
      var p = m === months - 1 ? Math.round((bal + interest) * 100) / 100 : Math.min(pi, Math.round((bal + interest) * 100) / 100);
      bal = Math.max(0, bal + interest - p);
      if (withMi) miMonths++;
      pays.push(p + (withMi ? mi : 0));
    }
    return { pi: pi, mi: mi, miMonths: miMonths, pays: pays, total: pays.reduce(function (a, b) { return a + b; }, 0) };
  }
  // --- end pure ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function cell(row, text) { var td = document.createElement('td'); td.textContent = text; row.appendChild(td); }
  function pct(v) { return v.toFixed(3) + '%'; }

  var OUT = ['aprmApr', 'aprmRateOut', 'aprmGap', 'aprmPi', 'aprmMi', 'aprmFinanced', 'aprmPrepaid', 'aprmCharge', 'aprmTotal',
             'aprmOther', 'aprmTolerance', 'aprmLtv'];
  function clearAll() {
    OUT.forEach(function (id) { setText(id, '–'); });
    el('aprmFees').textContent = '';
    el('aprmSteps').textContent = '';
  }

  function update() {
    var loan = read('aprmLoan', NaN), value = read('aprmValue', NaN), rate = read('aprmRate', NaN), years = parseInt(el('aprmTerm').value, 10),
        points = read('aprmPoints', 0), orig = read('aprmOrig', 0), lender = read('aprmLender', 0), broker = read('aprmBroker', 0),
        days = read('aprmDays', 0), miPct = read('aprmPmi', 0), ufmi = read('aprmUfmi', 0),
        appraisal = read('aprmAppraisal', 0), credit = read('aprmCredit', 0), title = read('aprmTitle', 0), docs = read('aprmDocs', 0),
        appFee = read('aprmAppFee', 0);
    var msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(value) || value <= 0) msg = 'Enter the home value or purchase price.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if ([points, orig, lender, broker, days, miPct, ufmi, appraisal, credit, title, docs, appFee].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Fees, points and days cannot be negative.';
    else if (points > 10 || orig > 10) msg = 'Enter 10 points or fewer and an origination fee of 10% or less.';
    else if (days > 31 || days % 1 !== 0) msg = 'Enter whole days of prepaid interest, 0 to 31.';
    else if (miPct > 5) msg = 'Enter a mortgage insurance rate of 5% a year or less.';
    var months = years * 12;
    var pointsAmt = loan * points / 100, origAmt = loan * orig / 100, perDiem = Math.round(loan * rate / 100 / 365 * 100) / 100,
        interestAmt = perDiem * days;
    var prepaid = pointsAmt + origAmt + lender + broker + ufmi + interestAmt;
    if (!msg && prepaid >= loan) msg = 'Prepaid finance charges must be less than the loan amount.';
    el('aprmError').hidden = !msg;
    el('aprmError').textContent = msg;
    if (msg) { clearAll(); return; }

    var s = stream(loan, rate, months, value, miPct), net = loan - prepaid;
    var apr = solveApr(net, s.pays);
    if (isNaN(apr)) { clearAll(); return; }
    var other = appraisal + credit + title + docs + appFee;
    setText('aprmApr', pct(apr * 100));
    setText('aprmRateOut', pct(rate));
    var gap = apr * 100 - rate;
    setText('aprmGap', (gap >= 0 ? '+' : '') + gap.toFixed(3) + ' points (' + Math.round(gap * 100) + ' basis points)');
    setText('aprmPi', money.format(s.pi));
    setText('aprmMi', s.miMonths ? money.format(s.mi) + ' for ' + s.miMonths + ' payments' : 'None');
    setText('aprmLtv', (loan / value * 100).toFixed(1) + '%');
    setText('aprmFinanced', money.format(net));
    setText('aprmPrepaid', money.format(prepaid));
    setText('aprmCharge', money.format(s.total - net));
    setText('aprmTotal', money.format(s.total));
    setText('aprmOther', money.format(other));
    var irregular = s.miMonths > 0 && s.miMonths < months;
    setText('aprmTolerance', irregular ? '±0.250 points (payments change when mortgage insurance ends)' : '±0.125 points (regular payments)');

    var fees = [
      ['Discount points', pointsAmt, true, '1026.4(b)(3): points and loan fees'],
      ['Origination fee', origAmt, true, '1026.4(b)(3): points and loan fees'],
      ['Underwriting, processing and other lender fees', lender, true, '1026.4(b)(2)–(3): service charges and loan fees'],
      ['Mortgage broker fee', broker, true, '1026.4(a)(3): broker fees count even when a broker is optional'],
      ['Upfront mortgage insurance', ufmi, true, '1026.4(b)(5): insurance protecting the lender against default'],
      ['Prepaid interest (' + days + ' days at ' + money.format(perDiem) + ')', interestAmt, true, '1026.4(b)(1): interest, collected at closing'],
      ['Monthly mortgage insurance (in payments)', s.mi * s.miMonths, true, '1026.4(b)(5), paid until 78% of value'],
      ['Appraisal', appraisal, false, '1026.4(c)(7)(iv): real-estate fee, if bona fide and reasonable'],
      ['Credit report', credit, false, '1026.4(c)(7)(iii): real-estate fee'],
      ['Title search and title insurance', title, false, '1026.4(c)(7)(i): real-estate fee'],
      ['Document preparation and notary', docs, false, '1026.4(c)(7)(ii)–(iii): real-estate fees'],
      ['Application fee charged to every applicant', appFee, false, '1026.4(c)(1)']
    ];
    var body = el('aprmFees');
    body.textContent = '';
    fees.forEach(function (f) {
      if (f[1] <= 0) return;
      var tr = document.createElement('tr');
      cell(tr, f[0]);
      cell(tr, money.format(f[1]));
      cell(tr, f[2] ? 'Yes' : 'No');
      cell(tr, '§ ' + f[3]);
      body.appendChild(tr);
    });
    if (!body.children || body.children.length === 0) {
      var none = document.createElement('tr');
      cell(none, 'No fees entered');
      cell(none, money.format(0)); cell(none, '–'); cell(none, '–');
      body.appendChild(none);
    }

    // What drives the gap: add the charges one group at a time.
    var steps = [
      ['Note rate only', 0, 0, 0],
      ['+ points and origination fee', pointsAmt + origAmt, 0, 0],
      ['+ lender and broker fees', pointsAmt + origAmt + lender + broker, 0, 0],
      ['+ prepaid interest', pointsAmt + origAmt + lender + broker + interestAmt, 0, 0],
      ['+ mortgage insurance', prepaid, miPct, 1]
    ];
    var sb = el('aprmSteps'), prev = null;
    sb.textContent = '';
    steps.forEach(function (st) {
      var st2 = stream(loan, rate, months, value, st[2]);
      var a = solveApr(loan - st[1], st2.pays) * 100;
      var tr = document.createElement('tr');
      cell(tr, st[0]);
      cell(tr, isNaN(a) ? '–' : pct(a));
      cell(tr, prev === null || isNaN(a) ? '–' : '+' + Math.max(0, a - prev).toFixed(3));
      sb.appendChild(tr);
      prev = a;
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('aprmForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
